import {evaluate,sameResult,supportedFunctions,columnName,formulaFunctions} from './engine.mjs';
import {readState,persistState,validateState,blankState,STORAGE_KEY} from './state.mjs';
const app=document.querySelector('#app');
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escape;
const iconPaths={dashboard:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',path:'M5 3h14v18H5zM8 7h8M8 11h8M8 15h5',formula:'M16 3h-2c-3 0-3 3-3 5l-2 10c-.4 2-2 3-4 3M6 9h11',grid:'M3 3h18v18H3zM3 9h18M3 15h18M9 3v18M15 3v18',case:'M3 7h18v14H3zM8 7V3h8v4M3 12h18',bookmark:'M6 3h12v18l-6-4-6 4z',book:'M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3zM12 6v16',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14M15 15l6 6',check:'M5 12l4 4L19 6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 7v5l4 2',menu:'M3 6h18M3 12h18M3 18h18',download:'M12 3v12M7 10l5 5 5-5M4 17v4h16v-4',note:'M5 3h14v18H5zM8 7h8M8 11h8M8 15h5',moon:'M20 14A9 9 0 0 1 10 3a9 9 0 1 0 10 11'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="${iconPaths[name]||iconPaths.book}"/></svg>`;
const {state:initialState,error:stateError}=readState();let state=initialState;let data,route,filter='',category='',storageError=stateError,toastTimer;let siteConfig={aiAvailable:false,aiModel:null,chatgptLoginAvailable:false,user:null};
const ui={exerciseModes:{},caseChecks:{},sheet:{A1:'Produk',B1:'Jumlah',C1:'Harga',A2:'P001',B2:'3',C2:'25000',A3:'P002',B3:'5',C3:'15000',A4:'P003',B4:'2',C4:'40000',A5:'P004',B5:'4',C5:'20000',D2:'=B2*C2',D3:'=B3*C3',D4:'=B4*C4',D5:'=B5*C5'},lastFormula:'=SUM(D2:D5)'};
const nf=new Intl.NumberFormat('id-ID',{maximumFractionDigits:6});const show=v=>typeof v==='number'?nf.format(v):typeof v==='boolean'?(v?'TRUE':'FALSE'):String(v??'');
const level=id=>data.levels.find(x=>x.id===id);
const lesson=id=>data.lessons.find(x=>x.id===id);
const exercise=id=>data.exercises.find(x=>x.id===id);
const caseStudy=id=>data.caseStudies.find(x=>x.id===id);
const dataset=id=>data.datasets.find(x=>x.id===id);
const completed=(kind,id)=>state[kind].includes(id);
const progressFor=id=>{const lessons=data.lessons.filter(x=>x.levelId===id);const done=lessons.filter(x=>completed('completedLessons',x.id)).length;return {lessons,done,percent:lessons.length?Math.round(done/lessons.length*100):0}};
const nextLesson=()=>{const current=lesson(state.lastLesson);return current&&!completed('completedLessons',current.id)?current:data.lessons.find(x=>!completed('completedLessons',x.id))||data.lessons[0]};
const weakTopics=()=>{const latest=new Map;state.attempts.forEach(a=>latest.set(a.id,a));return [...latest.values()].filter(a=>!a.passed).map(a=>({attempt:a,item:exercise(a.id)||lesson(a.id)||caseStudy(a.id)})).filter(x=>x.item).slice(-6).reverse()};
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),4000)}
function save(){if(!persistState(state)){storageError='Progress belum tersimpan. Penyimpanan browser penuh atau diblokir. Ekspor cadangan agar pekerjaan Anda tetap aman.';toast(storageError);return false}storageError=null;return true}
function toggle(kind,id){const a=state[kind],i=a.indexOf(id);if(i<0)a.push(id);else a.splice(i,1);save()}
function attempt(id,passed,method){state.attempts.push({id,passed,method,at:new Date().toISOString()});if(state.attempts.length>5000)state.attempts=state.attempts.slice(-5000);if(passed&&exercise(id)&&!state.completedExercises.includes(id))state.completedExercises.push(id);save();const status=document.querySelector('[data-status-id="'+CSS.escape(id)+'"]');if(status&&state.completedExercises.includes(id)){status.textContent='Hasil sudah benar';status.classList.add('green')}}
function sources(items=[]){return `<div class="source">${items.filter(s=>/^https:\/\//.test(s.url||'')).map(s=>`<a href="${e(s.url)}" target="_blank" rel="noopener noreferrer">${e(s.title||'Microsoft Support')}</a>`).join('')}<p class="source-check">Sumber Microsoft diperiksa 6 Oktober 2026. Contoh dan penjelasan ditulis untuk pembelajaran.</p></div>`}
const paragraphs=a=>(Array.isArray(a)?a:[a]).filter(Boolean).map(x=>`<p>${e(x)}</p>`).join('');
const list=(a,ordered=false)=>`<${ordered?'ol':'ul'}>${(a||[]).map(x=>`<li>${e(x)}</li>`).join('')}</${ordered?'ol':'ul'}>`;
const pill=(text,cls='')=>`<span class="pill ${cls}">${e(text)}</span>`;
const btn=(text,href,cls='')=>`<a class="button ${cls}" href="${e(href)}">${e(text)}</a>`;
const bar=p=>`<div class="progressbar" role="progressbar" aria-valuenow="${p}" aria-valuemin="0" aria-valuemax="100" aria-label="Progress"><div style="width:${p}%"></div></div>`;
function head(title,description,actions=''){return `<div class="page-head"><div><h1>${e(title)}</h1>${description?`<p>${e(description)}</p>`:''}</div><div class="split-actions">${actions}</div></div>`}
function datasetView(ds,max=12){if(!ds)return '';return `<div class="table-wrap"><table><caption class="sr-only">${e(ds.id)} — data latihan</caption><thead><tr><th scope="col">Baris Excel</th>${ds.columns.map((c,i)=>`<th scope="col">${columnName(i)} · ${e(c)}</th>`).join('')}</tr></thead><tbody>${ds.rows.slice(0,max).map((r,i)=>`<tr><th scope="row">${i+2}</th>${r.map((v,ci)=>`<td>${e(ds.dateColumns?.includes(ci)&&typeof v==='number'?new Date(Date.UTC(1899,11,30)+v*86400000).toLocaleDateString('id-ID',{timeZone:'UTC'}):ds.percentColumns?.includes(ci)&&typeof v==='number'?nf.format(v*100)+'%':show(v))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="small muted">${ds.rows.length.toLocaleString('id-ID')} baris · Header di baris 1 · ${e(ds.sheetName||'Data')} · ${e(ds.provenance||'Data sintetis untuk latihan.')} ${ds.rows.length>max?`Menampilkan ${max} baris pertama; unduh workbook untuk seluruh data.`:''}</p>`}
function dataCells(ds){const cells={};if(!ds)return cells;[ds.columns,...ds.rows].forEach((r,ri)=>r.forEach((v,ci)=>cells[(ds.sheetName||'Data')+'!'+columnName(ci)+(ri+1)]=v??''));return cells}
function accountTop(){if(siteConfig.user){const name=siteConfig.user.name||siteConfig.user.email||'ChatGPT';const initials=name.trim().split(/\s+/).slice(0,2).map(x=>x[0]?.toUpperCase()||'').join('')||'AI';return `<span class="account-name">${e(name)}</span><button class="btn-small" data-action="logout">Keluar</button><span class="avatar" aria-hidden="true">${e(initials)}</span>`}if(siteConfig.chatgptLoginAvailable)return `<a class="button chatgpt-login" href="/auth/openai">Continue with ChatGPT</a>`;return `<span class="ai-status" title="Login ChatGPT menunggu OAuth client">${siteConfig.aiAvailable?'AI Tutor aktif':'AI Tutor belum aktif'}</span><span class="avatar" aria-hidden="true">AI</span>`}
function shell(){const nav=[['dashboard','Dashboard','dashboard'],['path','Jalur belajar','path'],['functions','Kamus fungsi','formula'],['playground','Formula playground','grid'],['exercises','Latihan workbook','grid'],['cases','Studi kasus','case'],['review','Tinjauan & catatan','bookmark'],['resources','Sumber & glosarium','book'],['settings','Pengaturan','settings']];app.innerHTML=`<aside class="sidebar" id="sidebar"><a class="brand" href="#dashboard"><img src="favicon.svg" alt="">Excel Lab</a><div class="side-label">RUANG BELAJAR</div><nav aria-label="Navigasi utama">${nav.map(([id,label,ic],i)=>(i===4?'<div class="side-label">PRAKTIK & TINJAUAN</div>':'')+`<a class="nav-link" data-nav="${id}" href="#${id}">${icon(ic)}${label}</a>`).join('')}</nav><div class="side-bottom"><span class="pill" id="platform-label">Excel for ${e(state.settings.platform)}</span><p class="small" style="margin-top:12px">Progress tersimpan di perangkat ini.</p><a href="#settings" style="color:#b2e9ca">Cadangkan progress</a></div></aside><div class="workspace"><header class="topbar"><button class="mobile-menu subtle" data-action="menu" aria-label="Buka navigasi" aria-expanded="false">${icon('menu')}</button><form class="searchbox" id="global-search-form">${icon('search')}<input id="global-search" name="q" maxlength="160" placeholder="Cari materi, fungsi, latihan…" aria-label="Cari seluruh materi" autocomplete="off"><span class="search-hint">⌘ K</span></form><div class="top-right">${accountTop()}</div></header><main id="main" tabindex="-1"></main></div>`}
function dashboard(){const done=data.lessons.filter(x=>completed('completedLessons',x.id)).length,total=data.lessons.length,pct=Math.round(done/total*100),next=nextLesson(),lvl=level(next.levelId),weak=weakTopics();return head(done?'Lanjutkan perjalanan belajar Anda.':'Selamat datang di ruang belajar.','Pelajari konsep, coba formula, lalu terapkan pada data nyata.',pill('Excel for '+state.settings.platform,'green'))+`<div class="stats"><div class="stat">${icon('path')}<span>Progress keseluruhan</span><div class="stat-value">${pct}%</div>${bar(pct)}</div><div class="stat">${icon('book')}<span>Pelajaran selesai</span><div class="stat-value">${done} <small class="muted">/ ${total}</small></div><span>${e(lvl?.title||'Dasar Excel')}</span></div><div class="stat">${icon('grid')}<span>Latihan selesai</span><div class="stat-value">${state.completedExercises.filter(id=>exercise(id)).length} <small class="muted">/ ${data.exercises.length}</small></div><span>Hasil latihan yang sudah benar</span></div><div class="stat">${icon('case')}<span>Studi kasus selesai</span><div class="stat-value">${state.completedCases.filter(id=>caseStudy(id)).length} <small class="muted">/ ${data.caseStudies.length}</small></div><span>Proyek yang Anda evaluasi</span></div></div><div class="grid2"><section class="card continue"><div class="eyebrow">${done?'REKOMENDASI BERIKUTNYA':'MULAI DARI FONDASI'}</div><h2>${e(next.title)}</h2><p>${e(next.objectives?.[0]||lvl.description)}</p><div class="meta"><span>${e(lvl.title)}</span><span>${icon('clock')} ${next.minutes} menit</span></div>${btn(state.lastLesson===next.id?'Lanjutkan pelajaran':'Mulai pelajaran','#lesson/'+next.id,'primary')}</section><section class="card"><div class="eyebrow">LANGKAH BELAJAR</div><h2 style="margin-top:14px">Dari paham ke bisa.</h2><a class="quick-link" href="#playground">${icon('formula')}<div><div class="row-title">Coba sebuah formula</div><div class="small muted">Sel, range, dan feedback langsung</div></div></a><a class="quick-link" href="#exercises">${icon('download')}<div><div class="row-title">Kerjakan di Excel ${e(state.settings.platform)}</div><div class="small muted">Unduh, kerjakan, unggah hasil</div></div></a><a class="quick-link" href="#review">${icon('note')}<div><div class="row-title">Buka catatan belajar</div><div class="small muted">${Object.values(state.notes).filter(Boolean).length} catatan · ${state.bookmarks.length} bookmark</div></div></a></section></div><div class="grid2"><section><div class="section-title"><h2>Jalur belajar Anda</h2><a href="#path">Lihat semua level</a></div><div class="card">${data.levels.slice(0,5).map((l,i)=>{const p=progressFor(l.id);return `<a class="path-row" href="#path/${l.id}"><span class="path-num ${l.id===next.levelId?'current':''}">${String(i+1).padStart(2,'0')}</span><div class="grow"><div class="row-title">${e(l.title)}</div><span class="small muted">${p.lessons.length} pelajaran · ${p.done} selesai</span></div>${pill(p.percent+'%',p.percent===100?'green':'')}</a>`}).join('')}</div></section><section><div class="section-title"><h2>Perlu ditinjau</h2></div><div class="card">${weak.length?weak.map(({item})=>`<a class="quick-link" href="#${exercise(item.id)?'exercise':lesson(item.id)?'lesson':'case'}/${e(item.id)}">${icon('book')}<div><div class="row-title">${e(item.title)}</div><div class="small muted">Upaya terakhir perlu diperbaiki</div></div></a>`).join(''):`<p class="muted">Belum ada topik lemah. Setelah berlatih, bagian ini menampilkan topik dari upaya terakhir yang belum berhasil.</p>${btn('Pilih latihan pertama','#exercises')}`}</div><div class="tip small"><strong>Belajar di Mac</strong><p style="margin-top:7px">Gunakan shortcut khusus Mac. Nama fungsi contoh memakai bahasa Inggris; pemisah argumen Excel Anda bisa berupa koma atau titik koma.</p><a href="#resources/platforms">Lihat panduan platform</a></div></section></div>`}
function pathPage(selected){return head('Jalur belajar','Kuasai fondasi sebelum melanjutkan. Prasyarat menjadi panduan; Anda tetap dapat membuka semua materi.')+data.levels.map((l,i)=>{const p=progressFor(l.id),prereqs=(l.prerequisites||[]).map(id=>level(id)?.title||id);return `<details class="lesson-group" ${!selected||selected===l.id?'open':''}><summary><span class="path-num ${p.done?'current':''}" style="display:inline-grid;margin-right:12px">${String(i+1).padStart(2,'0')}</span>${e(l.title)} <span class="small muted">${p.done}/${p.lessons.length}</span></summary><p class="muted">${e(l.description)}</p>${prereqs.length?`<p class="small"><strong>Prasyarat:</strong> ${e(prereqs.join(', '))}</p>`:''}${l.id==='data-model'?'<div class="tip warning small">Data Model/Power Pivot tidak didukung Excel Mac. Pelajari konsep di sini; praktik native memerlukan Excel Windows yang mendukung Power Pivot.</div>':''}${bar(p.percent)}${p.lessons.map(x=>`<div class="list-row"><span class="path-num ${completed('completedLessons',x.id)?'current':''}">${completed('completedLessons',x.id)?icon('check'):icon('book')}</span><div class="grow"><div class="row-title"><a href="#lesson/${x.id}">${e(x.title)}</a></div><div class="small muted">${e(x.objectives?.[0]||'')} · ${x.minutes} menit</div></div>${btn(completed('completedLessons',x.id)?'Tinjau':'Pelajari','#lesson/'+x.id,'btn-small')}</div>`).join('')}</details>`}).join('')}
function lessonPage(id){if(id&&!lesson(id))return notFound();const l=lesson(id)||data.lessons[0];state.lastLesson=l.id;save();const lvl=level(l.levelId),related=data.exercises.filter(x=>x.lessonId===l.id||(x.levelId===l.levelId&&(!l.functions?.length||x.requiredFunctions?.some(f=>l.functions.includes(f))))).slice(0,4),cases=data.caseStudies.filter(x=>x.levelId===l.levelId||x.functions?.some(f=>l.functions?.includes(f))).slice(0,2);return head(l.title,lvl.title+' · '+l.minutes+' menit',btn('Kembali ke jalur','#path/'+lvl.id))+`<div class="lesson-layout"><article class="card article"><div class="meta">${pill(lvl.title,'green')}${completed('completedLessons',l.id)?pill('Selesai','green'):pill('Belum selesai')}</div><h2 id="tujuan">Tujuan belajar</h2>${list(l.objectives)}${l.prerequisites?.length?`<p class="small muted">Pelajari dahulu: ${l.prerequisites.map(id=>lesson(id)?`<a href="#lesson/${id}">${e(lesson(id).title)}</a>`:e(level(id)?.title||id)).join(', ')}.</p>`:''}<h2 id="konsep">Konsep dan kegunaan</h2>${paragraphs(l.concepts)}<h2 id="langkah">Langkah di Excel</h2>${list(l.steps,true)}${l.platformNote?`<div class="tip small"><strong>Catatan platform</strong><p style="margin-top:7px">${e(l.platformNote)}</p></div>`:''}<h2 id="contoh">Contoh yang dapat dicoba</h2>${(l.examples||[]).map(ex=>`<div class="example"><h3>${e(ex.title)}</h3>${ex.formula?`<pre>${e(ex.formula)}</pre>`:''}${paragraphs(ex.explanation)}${ex.result!=null?`<p><strong>Hasil:</strong> ${e(ex.result)}</p>`:''}</div>`).join('')}<h2 id="nyata">Penerapan dunia nyata</h2>${paragraphs(l.realWorld)}<h2 id="kesalahan">Kesalahan umum</h2>${list(l.mistakes)}<h3>Tips penggunaan</h3>${list(l.tips)}${l.functions?.length?`<div class="toolbar">${l.functions.filter(f=>data.functions.some(x=>x.name===f)).map(f=>`<a class="pill" href="#functions/${f}">${e(f)}</a>`).join('')}</div>`:''}<h2 id="praktik">Coba sendiri</h2><p>${e(l.practice?.prompt)}</p><form id="lesson-practice" data-id="${l.id}"><label class="sr-only" for="practice-answer">Jawaban praktik</label><input id="practice-answer" class="full" name="answer" placeholder="Tulis jawaban Anda" required><button class="primary" style="margin-top:12px">Periksa jawaban</button></form><div id="practice-feedback" aria-live="polite"></div><details><summary>Petunjuk jawaban dan pembahasan</summary><pre>${e(l.practice?.answer)}</pre><p>${e(l.practice?.explanation)}</p></details><h2 id="exercise">Exercise</h2>${related.length?related.map(x=>`<a class="list-row" href="#exercise/${x.id}">${icon('grid')}<div class="grow"><div class="row-title">${e(x.title)}</div><div class="small muted">${e(x.difficulty)} · Workbook .xlsx</div></div>${pill(completed('completedExercises',x.id)?'Selesai':'Latihan')}</a>`).join(''):`<p>Praktikkan langkah di atas pada workbook baru di Excel. Tinjau hasil dengan kesalahan umum dan evaluasi di bawah.</p>${btn('Buka bank latihan','#exercises')}`}<h2 id="case">Studi kasus</h2>${cases.length?cases.map(c=>`<a class="list-row" href="#case/${c.id}">${icon('case')}<div class="grow row-title">${e(c.title)}</div>${pill('Proyek')}</a>`).join(''):`<p>Gunakan konsep ini pada proyek keuangan, penjualan, atau konstruksi.</p>${btn('Pilih studi kasus','#cases')}`}<h2 id="evaluasi">Evaluasi pemahaman</h2><form id="lesson-quiz" data-id="${l.id}"><p><strong>${e(l.quiz?.question)}</strong></p>${(l.quiz?.options||[]).map((o,i)=>`<label class="choice"><input type="radio" name="answer" value="${i}" required>${e(o)}</label>`).join('')}<button class="primary" style="margin-top:12px">Periksa pemahaman</button></form><div id="quiz-feedback" aria-live="polite"></div><h2 id="sumber">Sumber materi</h2>${sources(l.sources)}<div class="divider"></div><button data-action="complete-lesson" data-id="${l.id}" class="${completed('completedLessons',l.id)?'':'primary'}">${icon('check')}${completed('completedLessons',l.id)?'Batalkan tanda selesai':'Tandai pelajaran selesai'}</button>${(()=>{const n=data.lessons[data.lessons.indexOf(l)+1];return n?`<div style="margin-top:17px">${btn('Pelajaran berikutnya: '+n.title,'#lesson/'+n.id)}</div>`:''})()}</article><aside class="card toc"><h3>DALAM PELAJARAN INI</h3>${['Tujuan','Konsep','Langkah','Contoh','Praktik','Exercise','Evaluasi','Sumber'].map((t,i)=>`<a href="#" data-scroll="${['tujuan','konsep','langkah','contoh','praktik','exercise','evaluasi','sumber'][i]}">${e(t)}</a>`).join('')}<div class="divider"></div><button class="full" data-action="bookmark" data-id="${l.id}">${icon('bookmark')}${state.bookmarks.includes(l.id)?'Hapus bookmark':'Bookmark'}</button><button class="full" data-action="review-later" data-id="${l.id}">${icon('clock')}${state.reviewLater.includes(l.id)?'Hapus dari tinjauan':'Tinjau nanti'}</button><label class="block small" for="lesson-note" style="margin-top:19px"><strong>Catatan pribadi</strong></label><textarea id="lesson-note" rows="7" maxlength="30000" data-note-id="${l.id}" placeholder="Apa yang ingin Anda ingat?">${e(state.notes[l.id]||'')}</textarea><button class="full btn-small" data-action="save-note" data-id="${l.id}">Simpan catatan</button><span class="status-inline" id="note-status" aria-live="polite"></span></aside></div>`}
function functionPage(id){const funcs=data.functions.filter(f=>(!category||f.category===category)&&[f.name,f.purpose,f.syntax].join(' ').toLowerCase().includes(filter.toLowerCase()));const f=funcs.find(x=>x.name===id)||funcs[0];return head('Kamus fungsi','Cari tujuan, sintaks, dan contoh fungsi sebelum menggunakannya.')+`<div class="toolbar"><input id="catalog-filter" placeholder="Cari SUMIFS, lookup, teks…" value="${e(filter)}" aria-label="Cari fungsi"><select id="catalog-category" aria-label="Kategori fungsi"><option value="">Semua kategori</option>${[...new Set(data.functions.map(x=>x.category))].map(c=>`<option ${category===c?'selected':''}>${e(c)}</option>`).join('')}</select><span class="small muted">${funcs.length} fungsi</span></div>${!funcs.length?'<div class="card empty"><h2>Fungsi tidak ditemukan</h2><p>Gunakan nama fungsi atau hapus filter kategori.</p></div>':`<div class="function-list"><nav class="card function-index" aria-label="Daftar fungsi">${funcs.map(x=>`<a class="${x.name===f?.name?'active':''}" href="#functions/${x.name}"><strong>${e(x.name)}</strong><div class="small muted">${e(x.category)}</div></a>`).join('')}</nav><article class="card article"><div class="meta">${pill(f.category)}${pill(f.difficulty,'green')}</div><h2 style="font-size:1.8rem;margin-top:15px">${e(f.name)}</h2><p>${e(f.purpose)}</p><h3>Syntax</h3><pre>${e(f.syntax)}</pre><h3>Parameter</h3>${f.parameters.length?f.parameters.map(p=>`<div class="param"><code>${e(p.name)}</code><span>${e(p.description)}</span></div>`).join(''):'<p class="muted">Fungsi ini tidak memerlukan argumen.</p>'}<h2>Contoh</h2><pre>${e(f.example)}</pre><p><strong>Hasil:</strong> ${e(f.result)}</p><p><strong>Penerapan:</strong> ${e(f.realWorld)}</p><h2>Kesalahan umum</h2>${list(f.mistakes)}<h3>Alternatif</h3>${list(f.alternatives)}<div class="tip small"><strong>Dukungan versi</strong><p style="margin-top:7px">${e(f.availability)}</p></div><div class="split-actions">${supportedFunctions.includes(f.name)?`<button data-action="try-function" data-id="${f.name}" class="primary">Coba di playground</button>`:pill('Praktik fungsi ini di Excel')} ${btn('Temukan materi terkait','#search/'+encodeURIComponent(f.name))}</div><h2>Referensi</h2>${sources([f.source])}</article></div>`}`}
function numericSheet(){return Object.fromEntries(Object.entries(ui.sheet).map(([k,v])=>[k,v!==''&&String(v).trim()!==''&&Number.isFinite(Number(v))?Number(v):v]))}
function playground(){const cells=numericSheet();return head('Formula playground','Ubah isi sel dan coba formula. Referensi, range, dan fungsi dasar mendapat feedback langsung.')+`<div class="grid2 equal"><section class="card"><h2>Coba formula</h2><form id="playground-form"><label for="playground-formula" class="small block">Formula</label><input id="playground-formula" class="formula-input" value="${e(ui.lastFormula)}" placeholder="=SUM(D2:D5)" autocomplete="off" required><button class="primary" style="margin-top:14px">Hitung formula</button></form><div id="playground-feedback" aria-live="polite"></div><div class="toolbar"><button class="btn-small" data-action="preset" data-formula="=SUM(D2:D5)">SUM</button><button class="btn-small" data-action="preset" data-formula='=IF(B2>=3,"Banyak","Sedikit")'>IF</button><button class="btn-small" data-action="preset" data-formula='=COUNTIF(B2:B5,">=3")'>COUNTIF</button><button class="btn-small" data-action="preset" data-formula='=SUMIF(B2:B5,">=3",D2:D5)'>SUMIF</button><button class="btn-small" data-action="preset" data-formula='=XLOOKUP("P003",A2:A5,C2:C5,"Tidak ada")'>XLOOKUP</button></div><div class="tip small">Angka desimal memakai titik pada playground. Koma dan titik koma diterima sebagai pemisah argumen. XLOOKUP, VLOOKUP, MATCH hanya mendukung exact match di sini.</div><details><summary>Fungsi yang didukung (${supportedFunctions.length})</summary><p class="small">${e(supportedFunctions.join(', '))}</p><p class="small muted">Belum mendukung structured references, named ranges, spill arrays, chart, PivotTable, Power Query, VBA, atau seluruh perilaku Excel. Gunakan workbook untuk kemampuan tersebut.</p></details><button data-action="reset-sheet" class="btn-small">Pulihkan dataset contoh</button></section><section class="card"><div class="section-title" style="margin-top:0"><h2>Sheet1</h2><span class="small muted">A1:F10</span></div><div class="table-wrap"><table class="sheet"><thead><tr><th></th>${Array.from({length:6},(_,c)=>`<th scope="col">${columnName(c)}</th>`).join('')}</tr></thead><tbody>${Array.from({length:10},(_,r)=>`<tr><th scope="row">${r+1}</th>${Array.from({length:6},(_,c)=>{const key=columnName(c)+(r+1),v=ui.sheet[key]||'',res=String(v).startsWith('=')?evaluate(String(v),cells):null;return `<td><input aria-label="Sel ${key}" data-cell="${key}" value="${e(v)}">${res?`<span class="sheet-result" data-cell-result="${key}">${e(res.error||show(res.value))}</span>`:''}</td>`}).join('')}</tr>`).join('')}</tbody></table></div><p class="small muted">Masukkan angka, teks, atau formula yang diawali =. Rumus pada sel dihitung ulang saat Anda berpindah sel.</p></section></div>`}
function filtered(items){return items.filter(x=>(!category||x.levelId===category)&&[x.title,x.instructions,x.scenario,...(x.requiredFunctions||x.functions||[])].join(' ').toLowerCase().includes(filter.toLowerCase()))}
function catalogPage(kind){const isCase=kind==='cases',items=filtered(isCase?data.caseStudies:data.exercises),doneKey=isCase?'completedCases':'completedExercises';const aiBox=isCase?'':`<section class="card ai-recommend-card"><div><div class="eyebrow">CHATGPT · LATIHAN ADAPTIF</div><h2>Rekomendasi berdasarkan hasil latihanmu</h2><p class="muted">AI membaca riwayat benar/salah yang tersimpan di browser ini, lalu memilih latihan berikutnya dan membuat tantangan tambahan.</p></div><button class="primary" data-action="ai-recommend" ${siteConfig.aiAvailable?'':'disabled'}>${siteConfig.aiAvailable?'Buat rekomendasi':'AI belum dikonfigurasi'}</button><div id="ai-recommendations" class="ai-recommendations" aria-live="polite"></div></section>`;return head(isCase?'Studi kasus':'Latihan workbook',isCase?'Kerjakan proyek dari data mentah sampai analisis yang dapat dijelaskan.':'Praktikkan konsep melalui hasil, formula, dan workbook Excel nyata.')+aiBox+`<div class="toolbar"><input id="catalog-filter" placeholder="Cari ${isCase?'konstruksi, dashboard…':'SUMIFS, lookup, penjualan…'}" value="${e(filter)}" aria-label="Cari ${isCase?'studi kasus':'latihan'}"><select id="catalog-category" aria-label="Filter level"><option value="">Semua level</option>${data.levels.map(l=>`<option value="${l.id}" ${category===l.id?'selected':''}>${e(l.title)}</option>`).join('')}</select><span class="small muted">${items.length} ${isCase?'proyek':'latihan'}</span></div>${items.length?`<div class="catalog">${items.map((x,i)=>`<article class="card"><div class="meta">${pill(level(x.levelId)?.title||x.levelId,'green')}${completed(doneKey,x.id)?pill('Selesai','green'):pill(isCase?'Studi kasus':x.difficulty)}</div><h3>${e(x.title)}</h3><p>${e((isCase?x.scenario:x.objective||x.instructions).slice(0,190))}</p><div class="small muted" style="margin-bottom:18px">${(x.functions||x.requiredFunctions||[]).map(e).join(' · ')||'Praktik di workbook'}</div>${btn(isCase?'Buka proyek':'Kerjakan latihan','#'+(isCase?'case':'exercise')+'/'+x.id)}</article>`).join('')}</div>`:'<div class="card empty"><h2>Tidak ada hasil untuk filter ini</h2><p>Coba kata kunci lain atau pilih semua level.</p></div>'}`}
function workbookLink(item,label='Unduh exercise .xlsx'){return `<a class="button primary" href="workbooks/${encodeURIComponent(item.workbook)}" download>${icon('download')}${e(label)}</a>`}
function uploadBox(item,kind){return `<div class="upload-box"><h3>Unggah hasil Excel</h3><p class="small muted">Buka workbook di Excel ${e(state.settings.platform)}, isi sel jawaban, hitung ulang, lalu simpan. File diproses di perangkat Anda; maksimal 10 MB.</p><label class="small" for="workbook-upload">Pilih .xlsx untuk dievaluasi</label><input id="workbook-upload" type="file" accept=".xlsx" data-upload-id="${item.id}" data-upload-kind="${kind}"><div id="upload-feedback" aria-live="polite"></div></div>`}
function exercisePage(id){const x=exercise(id);if(!x)return notFound();const ds=dataset(x.datasetId),mode=ui.exerciseModes[id]||'result';return head(x.title,`${level(x.levelId)?.title||''} · ${x.difficulty}`,btn('Semua latihan','#exercises'))+`<div class="grid2"><article class="card article"><div class="meta">${pill(x.difficulty,'green')}<span class="pill ${completed('completedExercises',x.id)?'green':''}" data-status-id="${x.id}">${completed('completedExercises',x.id)?'Hasil sudah benar':'Belum selesai'}</span></div><h2>Tujuan dan instruksi</h2><p><strong>${e(x.objective)}</strong></p>${paragraphs(x.instructions)}<div class="tip small">Tulis jawaban workbook pada <strong>Jawaban!${e(x.targetCell)}</strong>. Dataset berada pada sheet <strong>${e(ds.sheetName||'Data')}</strong>; header di baris 1.</div><h2>Dataset</h2>${datasetView(ds)}<div class="split-actions">${workbookLink(x)}${btn('Panduan Excel '+state.settings.platform,'#resources/platforms')}</div><h2>Periksa jawaban di website</h2><p class="small muted">Mode hasil menerima nilai akhir. Mode formula menghitung formula pada dataset asli dan memeriksa fungsi target.</p><label class="small block" for="exercise-mode">Mode evaluasi</label><select id="exercise-mode" data-id="${x.id}"><option value="result" ${mode==='result'?'selected':''}>Hasil akhir</option><option value="formula" ${mode==='formula'?'selected':''}>Formula + hasil</option></select><form id="exercise-answer-form" data-id="${x.id}" style="margin-top:15px"><label class="small block" for="exercise-answer">${mode==='result'?'Jawaban akhir (angka desimal memakai titik)':'Formula memakai referensi Data! (awali dengan =)'}</label><input class="${mode==='formula'?'formula-input':'full'}" id="exercise-answer" name="answer" placeholder="${mode==='formula'?'=SUM(Data!B2:B10)':'Masukkan hasil'}" required autocomplete="off"><button class="primary" style="margin-top:13px">Evaluasi jawaban</button></form><div id="exercise-feedback" aria-live="polite"></div><div id="ai-feedback" aria-live="polite"></div><details><summary>Hint</summary>${paragraphs(x.hint)}</details><details><summary>Expected result</summary><p><strong>${e(show(x.expected))}</strong>${typeof x.expected==='number'?` · Toleransi ${e(show(x.tolerance??0.01))}`:''}</p></details><details><summary>Solution dan penjelasan</summary><pre>${e(x.solution)}</pre>${paragraphs(x.explanation)}</details></article><aside class="stack"><section class="card"><h3>Alur workbook</h3><ol class="small"><li>Unduh workbook latihan.</li><li>Buka di Excel ${e(state.settings.platform)}.</li><li>Kerjakan pada sel jawaban.</li><li>Hitung ulang, lalu simpan .xlsx.</li><li>Unggah dan baca feedback.</li></ol>${uploadBox(x,'exercise')}</section><section class="card"><h3>Batas evaluasi</h3><p class="small muted">Upload memeriksa nilai yang tersimpan oleh Excel. Cache kosong akan meminta hitung ulang, bukan dianggap salah. Formula target diperiksa sebagai bukti fungsi yang digunakan; formula ekuivalen tidak dibuktikan secara umum.</p><p class="small muted">Grafik, PivotTable, query dan format perlu pemeriksaan manual. Jangan mengubah data sumber pada latihan formula.</p>${x.requiredFunctions?.length?`<div class="toolbar">${x.requiredFunctions.map(f=>data.functions.some(x=>x.name===f)?`<a class="pill" href="#functions/${f}">${e(f)}</a>`:pill(f)).join('')}</div>`:''}</section></aside></div>`}
function casePage(id){const c=caseStudy(id);if(!c)return notFound();const ds=dataset(c.datasetId),checks=state.caseChecks[id]||[];return head(c.title,level(c.levelId)?.title||'Studi kasus',btn('Semua studi kasus','#cases'))+`<div class="grid2"><article class="card article"><div class="meta">${pill('Proyek terapan','green')}${completed('completedCases',id)?pill('Selesai','green'):pill('Belum selesai')}</div><h2>Situasi</h2>${paragraphs(c.scenario)}<h2>Tugas proyek</h2>${list(c.tasks,true)}<h2>Dataset</h2>${datasetView(ds,10)}<div class="split-actions">${workbookLink(c,'Unduh template proyek .xlsx')}</div><h2>Hasil kontrol</h2><p>Isi sel kontrol pada sheet Jawaban. Nilai ini membantu memeriksa analisis; kualitas laporan tetap diperiksa dengan rubrik.</p><form id="case-controls" data-id="${id}">${c.checkpoints.map((p,i)=>`<label class="block small" for="control-${i}" style="margin-top:13px">${e(p.label)} · Jawaban!${e(p.cell)}</label><input id="control-${i}" name="control-${i}" class="full" placeholder="Hasil Anda" required>`).join('')}<button class="primary" style="margin-top:15px">Periksa hasil kontrol</button></form><div id="case-feedback" aria-live="polite"></div><details><summary>Nilai kontrol yang diharapkan</summary>${c.checkpoints.map(p=>`<p><strong>${e(p.label)}:</strong> ${e(show(p.expected))}</p>${p.solution?`<pre>${e(p.solution)}</pre>`:''}`).join('')}</details><h2>Rubrik evaluasi mandiri</h2><p class="small muted">Tinjau workbook Anda dan centang kriteria yang sudah terpenuhi. Website tidak menilai objek grafik, desain dashboard, atau kode VBA secara otomatis.</p>${c.rubric.map((r,i)=>`<label class="choice"><input type="checkbox" data-case-check="${id}" value="${i}" ${checks.includes(i)?'checked':''}>${e(r)}</label>`).join('')}<button data-action="complete-case" data-id="${id}" class="${completed('completedCases',id)?'':'primary'}" style="margin-top:15px">${completed('completedCases',id)?'Batalkan tanda selesai':'Tandai proyek selesai'}</button><h2>Referensi</h2>${sources(c.sources||[])}</article><aside class="stack"><section class="card"><h3>Evaluasi workbook</h3>${uploadBox(c,'case')}</section><section class="card"><h3>Catatan proyek</h3><textarea rows="8" maxlength="30000" data-note-id="case:${id}" placeholder="Temuan, keputusan, dan hal yang ingin diperbaiki…">${e(state.notes['case:'+id]||'')}</textarea><button class="full" data-action="save-note" data-id="case:${id}">Simpan catatan</button><span class="status-inline" id="note-status" aria-live="polite"></span></section></aside></div>`}
function reviewPage(){const links=ids=>ids.map(id=>lesson(id)).filter(Boolean).map(l=>`<a class="list-row" href="#lesson/${l.id}">${icon('book')}<div class="grow row-title">${e(l.title)}</div>${pill(level(l.levelId)?.title||'')}</a>`).join('');const notes=Object.entries(state.notes).filter(([,v])=>v.trim());return head('Tinjauan & catatan','Kembali ke materi yang disimpan dan pelajari kembali hasil latihan Anda.')+`<div class="grid2 equal"><section class="card"><h2>Bookmark (${state.bookmarks.length})</h2>${links(state.bookmarks)||'<p class="muted">Gunakan tombol Bookmark pada pelajaran untuk menyimpan materi di sini.</p>'}</section><section class="card"><h2>Tinjau nanti (${state.reviewLater.length})</h2>${links(state.reviewLater)||'<p class="muted">Tandai materi yang ingin Anda ulang dari halaman pelajaran.</p>'}</section></div><div class="section-title"><h2>Catatan pribadi</h2></div>${notes.length?`<div class="catalog">${notes.map(([id,n])=>{const isCase=id.startsWith('case:'),item=isCase?caseStudy(id.slice(5)):lesson(id);return `<article class="card"><h3>${e(item?.title||id)}</h3><p class="review-note">${e(n)}</p>${item?btn('Buka '+(isCase?'proyek':'pelajaran'),'#'+(isCase?'case':'lesson')+'/'+item.id):''}</article>`}).join('')}</div>`:'<div class="card"><p class="muted">Belum ada catatan. Tulis catatan pada pelajaran atau studi kasus; catatan tersimpan di perangkat ini.</p></div>'}<div class="section-title"><h2>Riwayat upaya</h2><span class="small muted">20 upaya terakhir</span></div><div class="card">${state.attempts.length?state.attempts.slice(-20).reverse().map(a=>{const x=exercise(a.id)||lesson(a.id)||caseStudy(a.id);return `<div class="list-row"><div class="grow"><div class="row-title">${e(x?.title||a.id)}</div><div class="small muted">${e(a.method)} · ${e(new Date(a.at).toLocaleString('id-ID'))}</div></div>${pill(a.passed?'Berhasil':'Perlu ditinjau',a.passed?'green':'amber')}</div>`}).join(''):'<p class="muted">Riwayat akan muncul setelah Anda memeriksa jawaban atau evaluasi.</p>'}</div>`}
function resourcesPage(section){return head('Sumber & glosarium','Rujukan Microsoft, istilah Excel, dan panduan perbedaan platform.')+`<div class="toolbar">${btn('Dokumentasi','#resources')}${btn('Windows · Mac · Web','#resources/platforms')}${btn('Glosarium','#resources/glossary')}</div>${section==='platforms'?platformPage():section==='glossary'?glossaryPage():`<div class="resource-grid">${data.resources.map(s=>`<article class="card"><div class="eyebrow">MICROSOFT ${s.url?.includes('learn.microsoft')?'LEARN':'SUPPORT'}</div><h3 style="margin-top:13px">${e(s.title)}</h3>${s.facts?.length?paragraphs(s.facts.slice(0,1)):''}<a href="${e(s.url)}" target="_blank" rel="noopener noreferrer">Buka dokumentasi resmi</a><p class="source-check" style="margin-top:12px">Diperiksa 6 Oktober 2026</p></article>`).join('')}</div><div class="tip small">Setiap pelajaran dan fungsi menyimpan sumber spesifik. Gunakan Microsoft Support untuk sintaks dan fitur; contoh dataset di platform ini merupakan data sintetis.</div>`}`}
function platformPage(){return `<section class="card article"><h2>Excel Mac sebagai jalur utama</h2><p>macOS Sonoma tidak menentukan versi Excel Anda. Periksa menu Excel &gt; About Microsoft Excel untuk versi/build dan jenis lisensi sebelum mengikuti fitur modern.</p><div class="table-wrap"><table><thead><tr><th>Fitur</th><th>Windows</th><th>Mac</th><th>Web</th></tr></thead><tbody><tr><td>Workbook, formula, tabel, grafik</td><td>Didukung</td><td>Didukung</td><td>Didukung; menu dan sebagian fitur berbeda</td></tr><tr><td>Power Query</td><td>2016+ / Microsoft 365; connector tergantung paket</td><td>Editor Microsoft 365 16.69+; connector berbeda</td><td>Import/edit/refresh sesuai paket dan connector</td></tr><tr><td>Power Pivot / Data Model</td><td>Paket Excel yang mendukung Power Pivot</td><td>Data Model tidak didukung</td><td>Tidak menjadi jalur pembuatan model pada kursus ini</td></tr><tr><td>VBA</td><td>Desktop</td><td>Desktop; sandbox/API berbeda</td><td>Tidak membuat, mengedit, atau menjalankan VBA</td></tr><tr><td>Office Scripts</td><td>Build/lisensi yang didukung</td><td>Build/lisensi yang didukung</td><td>Lisensi/admin yang didukung</td></tr><tr><td>XLOOKUP, LET, dynamic arrays</td><td>Microsoft 365 atau Excel 2021+</td><td>Microsoft 365 atau Excel 2021+</td><td>Didukung pada Excel Web modern</td></tr><tr><td>LAMBDA</td><td>Microsoft 365 / Excel 2024</td><td>Microsoft 365 / Excel 2024</td><td>Lihat dukungan pada sumber LAMBDA</td></tr></tbody></table></div><h2>Shortcut yang sering dipakai</h2><div class="table-wrap"><table><thead><tr><th>Tindakan</th><th>Mac</th><th>Windows</th></tr></thead><tbody><tr><td>Simpan</td><td>⌘ S</td><td>Ctrl S</td></tr><tr><td>Format Cells</td><td>⌘ 1</td><td>Ctrl 1</td></tr><tr><td>Edit cell</td><td>Control U</td><td>F2</td></tr><tr><td>Ganti relative/absolute reference</td><td>⌘ T atau F4 saat mengedit formula</td><td>F4</td></tr><tr><td>AutoSum</td><td>Shift ⌘ T</td><td>Alt =</td></tr><tr><td>Filter</td><td>⌘ Shift F atau Control Shift L</td><td>Ctrl Shift L</td></tr><tr><td>VBA Editor</td><td>Option F11</td><td>Alt F11</td></tr></tbody></table></div><p class="small muted">Function key dapat memerlukan Fn dan shortcut bisa bertabrakan dengan macOS. Dokumentasi Microsoft menggunakan layout keyboard US. Di Web, shortcut berbagi perilaku dengan browser.</p><h2>Alur integrasi yang tersedia</h2><p>Unduh workbook, buka di Excel Mac, kerjakan, hitung ulang dan simpan, kemudian unggah. Website memproses file yang Anda pilih secara lokal; tidak mengontrol aplikasi Excel desktop.</p><p>Untuk formula hasil upload, nilai cache tersimpan mungkin kosong atau usang. Jika kosong, buka kembali di Excel, pastikan calculation otomatis atau jalankan Calculate Now melalui menu Formulas, lalu simpan. Penilaian formula memeriksa fungsi target dan nilai akhir secara terpisah.</p><p>Office Scripts adalah pilihan tambahan jika tab Automate tersedia sesuai lisensi/admin. Aplikasi ini tidak menghubungkan atau menjalankan Office Scripts.</p><h2>Catatan dan sumber Microsoft</h2>${data.platforms.sources.filter(s=>['power-query-mac','power-query-web','power-query-connectors','data-model-mac','vba-mac','vba-web','office-scripts','excel2021-mac','lambda','shortcuts'].includes(s.id)).map(s=>`<details><summary>${e(s.title)}</summary>${list(s.facts||[])}${sources([s])}</details>`).join('')}</section>`}
function glossaryPage(){const terms=data.glossary.filter(g=>[g.term,g.definition].join(' ').toLowerCase().includes(filter.toLowerCase()));return `<div class="toolbar"><input id="catalog-filter" value="${e(filter)}" placeholder="Cari cell, range, measure…" aria-label="Cari istilah"></div><div class="card">${terms.length?terms.map(g=>`<div class="list-row" style="display:block"><h3>${e(g.term)}</h3><p class="muted" style="margin-bottom:0">${e(g.definition)}</p></div>`).join(''):'<p class="muted">Istilah tidak ditemukan.</p>'}</div>`}
function searchItems(query){const q=query.trim().toLowerCase();if(!q)return [];const groups=[['lesson','Pelajaran',data.lessons],['functions','Fungsi',data.functions],['exercise','Latihan',data.exercises],['case','Studi kasus',data.caseStudies],['resources/glossary','Istilah',data.glossary]];return groups.flatMap(([type,label,items])=>items.filter(x=>[x.title,x.name,x.term,x.purpose,x.definition,x.instructions,x.scenario,...(x.functions||x.requiredFunctions||[])].join(' ').toLowerCase().includes(q)).map(x=>({type,label,item:x,title:x.title||x.name||x.term,href:type==='resources/glossary'?'#resources/glossary':'#'+type+'/'+x.id}))).sort((a,b)=>(b.title.toLowerCase()===q)-(a.title.toLowerCase()===q))}
function searchPage(q){const results=searchItems(q);return head('Hasil pencarian',q?`“${q}” · ${results.length} hasil lintas materi`:'Cari pelajaran, fungsi, latihan, studi kasus, dan istilah.')+`<form id="search-page-form" class="toolbar"><input name="q" value="${e(q)}" placeholder="Misalnya: XLOOKUP" aria-label="Kata kunci pencarian" required><button class="primary">Cari</button></form><div class="card search-results">${results.length?results.map(({label,item,title,href})=>`<a class="list-row" href="${e(href)}"><span class="path-num">${icon(label==='Fungsi'?'formula':'book')}</span><div class="grow"><div class="row-title">${e(title)}</div><div class="small muted">${e((item.purpose||item.objectives?.[0]||item.objective||item.definition||item.scenario||'').slice(0,150))}</div></div>${pill(label)}</a>`).join(''):`<div class="empty"><h2>${q?'Tidak ada hasil':'Apa yang ingin Anda pelajari?'}</h2><p>${q?'Coba nama fungsi atau topik yang lebih singkat.':'Gunakan nama fungsi seperti SUMIFS atau istilah seperti PivotTable.'}</p></div>`}</div>`}
function settingsPage(){return head('Pengaturan','Sesuaikan ruang belajar dan simpan cadangan progress Anda.')+`<div class="grid2 equal"><section class="card"><h2>Preferensi belajar</h2><label class="block" for="platform-setting">Excel yang digunakan</label><select id="platform-setting" class="full" style="margin:8px 0 20px">${['Mac','Windows','Web'].map(x=>`<option ${x===state.settings.platform?'selected':''}>${x}</option>`).join('')}</select><p class="small muted">Materi utama ditulis untuk Excel Mac. Panduan perbedaan platform tetap tersedia untuk Windows dan Web.</p><label class="block" for="theme-setting">Tampilan</label><select id="theme-setting" class="full" style="margin-top:8px"><option value="light" ${state.settings.theme==='light'?'selected':''}>Terang</option><option value="dark" ${state.settings.theme==='dark'?'selected':''}>Gelap</option></select><div class="tip small">Progress, catatan, bookmark, dan riwayat tersimpan di browser pada perangkat ini. Perangkat atau alamat website berbeda tidak otomatis berbagi progress.</div></section><section class="card"><h2>Cadangan progress</h2><p>Ekspor cadangan secara berkala, terutama sebelum mengganti perangkat atau menghapus data browser.</p><button class="primary" data-action="export-progress">${icon('download')}Ekspor progress .json</button><div id="backup-download" aria-live="polite"></div><div class="divider"></div><label class="block" for="progress-import"><strong>Impor cadangan</strong></label><p class="small muted">Cadangan yang valid akan menggantikan progress saat ini setelah konfirmasi. File tidak dikirim ke server.</p><input id="progress-import" type="file" accept=".json,application/json" class="full"><details><summary>Impor dengan menempel JSON</summary><label class="block small" for="progress-paste">Tempel isi cadangan JSON</label><textarea id="progress-paste" rows="5" maxlength="5000000" placeholder="Tempel cadangan dari hasil ekspor"></textarea><button data-action="import-paste">Pulihkan dari JSON</button></details><div id="import-feedback" aria-live="polite"></div><p class="small muted" style="margin-top:20px">${state.updatedAt?'Terakhir disimpan: '+e(new Date(state.updatedAt).toLocaleString('id-ID')):'Belum ada aktivitas yang disimpan.'}</p></section></div><div class="card ai-settings" style="margin-top:24px"><div class="eyebrow">OPENAI</div><h2>ChatGPT & AI Tutor</h2>${siteConfig.user?`<p>Terhubung sebagai <strong>${e(siteConfig.user.name||siteConfig.user.email||'akun ChatGPT')}</strong>.</p><button data-action="logout">Keluar dari akun ChatGPT</button>`:siteConfig.chatgptLoginAvailable?`<p>Gunakan akun ChatGPT untuk masuk ke Excel Lab. Login hanya membagikan identitas dasar yang diizinkan; percakapan ChatGPT tidak otomatis dibagikan.</p><a class="button primary chatgpt-login" href="/auth/openai">Continue with ChatGPT</a>`:`<p class="muted">Login ChatGPT belum aktif karena website ini belum memiliki OpenAI OAuth client ID. Fitur AI Tutor tetap dapat berjalan memakai API key server.</p>`}<div class="meta" style="margin-top:16px">${pill(siteConfig.aiAvailable?'AI Tutor aktif':'AI Tutor belum aktif',siteConfig.aiAvailable?'green':'amber')}${siteConfig.aiAvailable?pill(siteConfig.aiModel||'OpenAI'):''}</div></div><div class="card" style="margin-top:24px"><h2>Data pribadi</h2><p class="muted">Workbook unggahan diproses sementara di browser dan tidak disimpan oleh aplikasi. Catatan dan progress dapat dihapus menggunakan tombol berikut.</p><button data-action="reset-progress" style="color:var(--red)">Hapus seluruh progress lokal</button></div>`}
function notFound(){return `<div class="card empty"><h1>Materi tidak ditemukan</h1><p>Tautan mungkin sudah berubah.</p>${btn('Buka jalur belajar','#path')}</div>`}
function syncSidebar(){const sidebar=document.querySelector('#sidebar');if(!sidebar)return;const narrow=matchMedia('(max-width:800px)').matches,open=sidebar.classList.contains('open');sidebar.inert=narrow&&!open;sidebar.setAttribute('aria-hidden',String(narrow&&!open));document.querySelector('[data-action=menu]').setAttribute('aria-expanded',String(open))}
function render(){const bits=location.hash.replace(/^#/,'').split('/');const type=bits[0]||'dashboard',id=(()=>{try{return decodeURIComponent(bits.slice(1).join('/'))}catch{return 'invalid-url'}})();route={type,id};document.body.classList.toggle('dark',state.settings.theme==='dark');document.querySelector('#platform-label').textContent='Excel for '+state.settings.platform;document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===({lesson:'path',exercise:'exercises',case:'cases',search:''}[type]||type)));const labels={dashboard:'Dashboard',path:'Jalur belajar',lesson:'Pelajaran',functions:'Kamus fungsi',playground:'Formula playground',exercises:'Latihan workbook',exercise:'Latihan',cases:'Studi kasus',case:'Studi kasus',review:'Tinjauan & catatan',resources:'Sumber & glosarium',settings:'Pengaturan',search:'Pencarian'};document.title=(labels[type]||'Excel Lab')+' — Excel Lab';let content;try{content=type==='dashboard'?dashboard():type==='path'?pathPage(id):type==='lesson'?lessonPage(id):type==='functions'?functionPage(id):type==='playground'?playground():type==='exercises'||type==='cases'?catalogPage(type):type==='exercise'?exercisePage(id):type==='case'?casePage(id):type==='review'?reviewPage():type==='resources'?resourcesPage(id):type==='settings'?settingsPage():type==='search'?searchPage(id):notFound()}catch(error){console.error(error);content=`<div class="card empty"><h1>Halaman belum dapat dimuat</h1><p>Coba muat ulang. Progress yang sudah tersimpan tetap ada.</p><button data-action="reload">Muat ulang</button></div>`}document.querySelector('#main').innerHTML=`<div class="breadcrumb">Ruang belajar / ${e(labels[type]||'Materi')}</div>${storageError?`<div class="tip warning" role="alert">${e(storageError)} <a href="#settings">Buka cadangan</a></div>`:''}${content}<p class="footer-note">Excel Lab · Belajar dengan data sintetis · Referensi Microsoft · Progress tersimpan lokal</p>`;if(type==='search')document.querySelector('#global-search').value=id;if(type==='playground')calculatePlayground();syncSidebar();}
function feedback(target,passed,title,detail=''){const el=document.querySelector(target);if(el)el.innerHTML=`<div class="feedback ${passed===null?'':passed?'good':'bad'}"><strong>${e(title)}</strong>${detail?`<p class="small" style="margin-top:8px">${e(detail)}</p>`:''}</div>`}
function calculatePlayground(){const input=document.querySelector('#playground-formula');if(!input)return;ui.lastFormula=input.value;const r=evaluate(input.value,numericSheet());feedback('#playground-feedback',r.error?false:true,r.error||'Hasil: '+show(r.value),r.error?'Periksa sintaks, referensi dan fungsi yang didukung.':'Dihitung pada data Sheet1 yang terlihat.');return r}
function renderAIFeedback(target,result){const el=document.querySelector(target);if(!el)return;el.innerHTML=`<section class="ai-feedback-card"><div class="ai-feedback-head"><span class="ai-badge">AI</span><div><strong>Feedback ChatGPT</strong><div class="small muted">${e(siteConfig.aiModel||'OpenAI')}</div></div></div><p><strong>${e(result.summary||'')}</strong></p><p>${e(result.explanation||'')}</p>${result.correction?`<div class="ai-correction"><span class="small muted">Koreksi yang disarankan</span><pre>${e(result.correction)}</pre></div>`:''}<p class="small"><strong>Tip:</strong> ${e(result.tip||'')}</p><p class="small muted"><strong>Latihan berikut:</strong> ${e(result.next_skill||'')}</p></section>`}
async function requestAIFeedback(x,payload,target='#ai-feedback'){const el=document.querySelector(target);if(!el)return;if(!siteConfig.aiAvailable){el.innerHTML='<div class="feedback"><strong>AI Tutor belum aktif.</strong><p class="small">Tambahkan OPENAI_API_KEY pada server untuk mengaktifkan koreksi ChatGPT.</p></div>';return}el.innerHTML='<div class="feedback ai-loading"><strong>ChatGPT sedang menganalisis jawaban…</strong><p class="small">Nilai benar/salah tetap ditentukan mesin latihan Excel Lab.</p></div>';try{const r=await fetch('/api/ai/grade',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({exerciseId:x.id,...payload})});const result=await r.json();if(!r.ok)throw Error(result.error||'AI belum dapat memberi feedback.');renderAIFeedback(target,result)}catch(error){el.innerHTML=`<div class="feedback"><strong>Feedback AI belum tersedia.</strong><p class="small">${e(error.message)}</p></div>`}}
function gradeExercise(x,answer,mode){let value=answer,formulaOk=true,detail;if(mode==='formula'){const result=evaluate(answer,dataCells(dataset(x.datasetId)),'Jawaban');if(result.error){feedback('#exercise-feedback',null,result.error,'Formula ini belum dapat dinilai. Anda dapat menggunakan mode hasil atau mengunggah workbook yang sudah dihitung di Excel.');return}value=result.value;const names=formulaFunctions(answer);formulaOk=(x.requiredFunctions||[]).every(f=>names.includes(f));detail='Hasil dihitung: '+show(value)+'. '+(formulaOk?'Fungsi target ditemukan.':'Gunakan fungsi target: '+x.requiredFunctions.join(', ')+'.')}else detail='Mode ini memeriksa nilai akhir. Gunakan mode formula untuk melatih fungsi target.';const passed=sameResult(value,x.expected,x.tolerance??0.01)&&formulaOk;attempt(x.id,passed,mode==='formula'?'Formula playground':'Hasil akhir');feedback('#exercise-feedback',passed,passed?'Jawaban benar. Progress latihan disimpan.':'Jawaban perlu diperbaiki.',detail+(passed?' '+x.explanation:' Baca hint dan periksa range, satuan, serta kriteria.'));requestAIFeedback(x,{answer,mode,passed,computedValue:value,formulaOk});}
async function readWorkbook(file){if(!file||!file.name.toLowerCase().endsWith('.xlsx'))throw Error('Pilih berkas .xlsx. Workbook dengan password harus dibuka dan disimpan tanpa password terlebih dahulu.');if(file.size>10*1024*1024)throw Error('File melebihi 10 MB. Gunakan workbook latihan yang tersedia.');const buffer=await file.arrayBuffer();return new Promise((resolve,reject)=>{const worker=new Worker(new URL('./workbook-worker.js',import.meta.url));const timer=setTimeout(()=>{worker.terminate();reject(Error('Workbook terlalu kompleks atau belum dapat dibaca. Simpan ulang workbook latihan di Excel.'))},12000);worker.onmessage=({data})=>{clearTimeout(timer);worker.terminate();data.error?reject(Error(data.error)):resolve(data)};worker.onerror=()=>{clearTimeout(timer);worker.terminate();reject(Error('Pembaca workbook tidak dapat dijalankan. Coba muat ulang halaman.'))};worker.postMessage({buffer},[buffer])})}
function checkDataset(rows,ds){const expected=[ds.columns,...ds.rows];if(rows.length<expected.length)return false;for(let i=0;i<expected.length;i++)for(let j=0;j<expected[i].length;j++){const a=rows[i]?.[j]??'',b=expected[i][j]??'';if(typeof b==='number'){if(typeof a!=='number'||Math.abs(a-b)>1e-8)return false}else if(String(a)!==String(b))return false}return true}
async function gradeUpload(input){const id=input.dataset.uploadId,kind=input.dataset.uploadKind,item=kind==='exercise'?exercise(id):caseStudy(id);if(!item||!input.files[0])return;input.disabled=true;feedback('#upload-feedback',null,'Membaca workbook…','File diproses di perangkat Anda.');try{const wb=await readWorkbook(input.files[0]);if(wb.cells.A2?.value!==id)throw Error('Workbook ini berasal dari latihan atau proyek lain. Unduh template yang sesuai pada halaman ini.');if(!checkDataset(wb.rows,dataset(item.datasetId)))throw Error('Data sumber berubah atau workbook tidak sesuai. Gunakan dataset asli dan tulis analisis pada sheet Jawaban atau sheet laporan baru.');const targets=kind==='exercise'?[{cell:item.targetCell,label:item.title,expected:item.expected,tolerance:item.tolerance}]:item.checkpoints;const results=targets.map(p=>{const c=wb.cells[p.cell];return {label:p.label,cell:p.cell,actual:c?.value??null,formula:c?.formula,expected:p.expected,tolerance:p.tolerance??item.tolerance??0.01}});if(results.some(r=>r.actual===null||r.actual==='')){feedback('#upload-feedback',null,'Nilai jawaban belum tersimpan.',`Isi ${results.filter(r=>r.actual===null||r.actual==='').map(r=>'Jawaban!'+r.cell).join(', ')}. Di Excel pilih calculation otomatis atau Calculate Now, simpan, lalu unggah kembali. Nilai kosong belum dinilai.`);return}const resultOk=results.every(r=>sameResult(r.actual,r.expected,r.tolerance));let formulaOk=true;if(kind==='exercise'&&item.requiredFunctions?.length){const names=formulaFunctions(results[0].formula);formulaOk=item.requiredFunctions.every(f=>names.includes(f));}const passed=resultOk&&formulaOk;attempt(id,passed,'Upload workbook');const text=results.map(r=>`${r.label}: ${show(r.actual)} ${sameResult(r.actual,r.expected,r.tolerance)?'(sesuai)':'(perlu ditinjau)'}`).join('. ');feedback('#upload-feedback',passed,passed?'Hasil workbook sesuai.':resultOk?'Nilai sesuai; formula target perlu ditinjau.':'Hasil workbook perlu diperbaiki.',text+(kind==='exercise'&&item.requiredFunctions?.length?(formulaOk?' Fungsi target ditemukan pada formula.':' Formula asli harus menggunakan '+item.requiredFunctions.join(', ')+'. Anda dapat memeriksa nilai saja melalui mode hasil.'):'')+(kind==='case'?' Lengkapi rubrik evaluasi mandiri sebelum menandai proyek selesai.':'')+' Nilai yang diperiksa adalah cache terakhir yang disimpan Excel; hasil belum dihitung ulang oleh Excel di website.');if(kind==='exercise'){const first=results[0];requestAIFeedback(item,{answer:first.formula||String(first.actual),mode:'upload-workbook',passed,computedValue:first.actual,formulaOk})}}catch(error){feedback('#upload-feedback',null,'Workbook belum dapat dievaluasi.',error.message)}finally{input.disabled=false}}
function renderAIRecommendations(result){const el=document.querySelector('#ai-recommendations');if(!el)return;const existing=(result.recommendedExerciseIds||[]).map(id=>exercise(id)).filter(Boolean);const drills=(result.extra_drills||[]).slice(0,3);el.innerHTML=`<div class="divider"></div><p><strong>${e(result.focus_summary||'Rekomendasi latihan')}</strong></p>${result.study_tip?`<p class="small muted">${e(result.study_tip)}</p>`:''}${existing.length?`<div class="ai-existing"><h3>Kerjakan berikutnya</h3>${existing.map(x=>`<a class="quick-link" href="#exercise/${e(x.id)}">${icon('grid')}<div><div class="row-title">${e(x.title)}</div><div class="small muted">${e((x.requiredFunctions||[]).join(' · ')||x.difficulty)}</div></div></a>`).join('')}</div>`:''}${drills.length?`<h3 style="margin-top:20px">Tantangan tambahan dari ChatGPT</h3><div class="ai-drill-grid">${drills.map(d=>`<article class="ai-drill"><div class="meta">${pill(d.difficulty||'Latihan')} ${pill(d.skill||'Excel','green')}</div><h4>${e(d.title)}</h4><p class="small">${e(d.task)}</p><details><summary>Hint</summary><p class="small">${e(d.hint)}</p></details></article>`).join('')}</div>`:''}`}
async function loadAIRecommendations(button){const el=document.querySelector('#ai-recommendations');if(!el)return;button.disabled=true;el.innerHTML='<div class="feedback ai-loading"><strong>ChatGPT sedang memilih latihan…</strong><p class="small">Riwayat latihan lokal digunakan untuk menemukan topik yang perlu diperkuat.</p></div>';try{const r=await fetch('/api/ai/recommend',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({completedExercises:state.completedExercises,attempts:state.attempts.slice(-40),platform:state.settings.platform})});const result=await r.json();if(result.recommendedExerciseIds?.length&&!r.ok){renderAIRecommendations({focus_summary:'AI belum tersedia, tetapi ini latihan yang dipilih dari riwayatmu.',study_tip:'Coba latihan berikut sambil konfigurasi API diperbaiki.',recommendedExerciseIds:result.recommendedExerciseIds,extra_drills:[]});return}if(!r.ok)throw Error(result.error||'Rekomendasi belum tersedia.');renderAIRecommendations(result)}catch(error){el.innerHTML=`<div class="feedback"><strong>Rekomendasi AI belum tersedia.</strong><p class="small">${e(error.message)}</p></div>`}finally{button.disabled=!siteConfig.aiAvailable}}
async function logoutChatGPT(){try{await fetch('/auth/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});location.reload()}catch{toast('Belum dapat keluar. Coba muat ulang.')}}
function exportProgress(){save();const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='excel-lab-progress-'+new Date().toISOString().slice(0,10)+'.json';const box=document.querySelector('#backup-download');if(box){box.innerHTML='<p class="small" style="margin-top:12px">Cadangan siap. Jika unduhan otomatis belum muncul, gunakan tautan berikut.</p>';a.textContent='Unduh file cadangan';a.className='button';box.append(a);const label=document.createElement('label');label.className='block small';label.textContent='Cadangan JSON (salin jika browser membatasi unduhan)';label.htmlFor='backup-json';label.style.marginTop='14px';const copy=document.createElement('textarea');copy.id='backup-json';copy.readOnly=true;copy.rows=5;copy.className='formula-input';copy.value=JSON.stringify(state,null,2);box.append(label,copy)}else document.body.append(a);a.click();toast('Cadangan progress siap diunduh.')}
async function importProgress(input){try{let text;if(typeof input==='string'){if(input.length>5*1024*1024)throw Error('Cadangan terlalu besar');text=input}else{const file=input.files[0];if(!file)return;if(file.size>5*1024*1024)throw Error('Cadangan terlalu besar (maksimal 5 MB).');text=await file.text()}const imported=validateState(JSON.parse(text));const validLessonIds=new Set(data.lessons.map(x=>x.id)),validExerciseIds=new Set(data.exercises.map(x=>x.id)),validCaseIds=new Set(data.caseStudies.map(x=>x.id));for(const k of ['completedLessons','bookmarks','reviewLater'])imported[k]=imported[k].filter(id=>validLessonIds.has(id));imported.completedExercises=imported.completedExercises.filter(id=>validExerciseIds.has(id));imported.completedCases=imported.completedCases.filter(id=>validCaseIds.has(id));if(!window.confirm('Impor cadangan akan menggantikan progress dan catatan di perangkat ini. Lanjutkan?'))return;const previous=state;state=imported;if(!persistState(state)){state=previous;throw Error('Cadangan valid, tetapi tidak dapat disimpan. Progress sebelumnya tetap digunakan.')}storageError=null;render();toast('Cadangan berhasil dipulihkan.')}catch(error){feedback('#import-feedback',false,'Cadangan belum diimpor.',error instanceof SyntaxError?'Isi file bukan JSON yang valid. Progress sebelumnya tetap ada.':error.message)}}
let filterTimer,noteTimer;
app.addEventListener('submit',event=>{const form=event.target;event.preventDefault();if(form.id==='global-search-form'||form.id==='search-page-form'){const q=new FormData(form).get('q').trim();if(q)location.hash='#search/'+encodeURIComponent(q)}else if(form.id==='playground-form')calculatePlayground();else if(form.id==='exercise-answer-form'){gradeExercise(exercise(form.dataset.id),new FormData(form).get('answer').trim(),ui.exerciseModes[form.dataset.id]||'result')}else if(form.id==='lesson-practice'){const l=lesson(form.dataset.id),raw=new FormData(form).get('answer').trim(),expected=String(l.practice.answer).trim();const normalize=s=>s.replace(/\s+/g,'').replace(/;/g,',').toLowerCase();const passed=sameResult(raw,expected,0.01)||normalize(raw)===normalize(expected);attempt(l.id,passed,'Praktik pelajaran');feedback('#practice-feedback',passed,passed?'Jawaban sesuai.':'Tinjau jawaban dan pembahasan.',l.practice.explanation+(passed?'':' Jika memakai formula atau langkah ekuivalen, bandingkan dengan pembahasan; pemeriksaan ini memakai jawaban contoh.'))}else if(form.id==='lesson-quiz'){const l=lesson(form.dataset.id),passed=Number(new FormData(form).get('answer'))===l.quiz.answerIndex;attempt(l.id,passed,'Evaluasi pemahaman');feedback('#quiz-feedback',passed,passed?'Pemahaman Anda tepat.':'Tinjau kembali konsepnya.',l.quiz.explanation)}else if(form.id==='case-controls'){const c=caseStudy(form.dataset.id),fd=new FormData(form),results=c.checkpoints.map((p,i)=>({p,actual:fd.get('control-'+i)})),passed=results.every(({p,actual})=>sameResult(actual,p.expected,p.tolerance??0.01));attempt(c.id,passed,'Hasil kontrol proyek');feedback('#case-feedback',passed,passed?'Semua hasil kontrol sesuai.':'Ada hasil kontrol yang perlu ditinjau.',results.map(({p,actual})=>`${p.label}: ${sameResult(actual,p.expected,p.tolerance??0.01)?'sesuai':'periksa kembali'}`).join('. '))}});
app.addEventListener('click',event=>{const scroll=event.target.closest('[data-scroll]');if(scroll){event.preventDefault();document.getElementById(scroll.dataset.scroll)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});return}const b=event.target.closest('[data-action]');if(!b)return;const id=b.dataset.id;switch(b.dataset.action){case 'menu':{const sidebar=document.querySelector('#sidebar');sidebar.classList.toggle('open');syncSidebar();break}case 'complete-lesson':toggle('completedLessons',id);render();toast(completed('completedLessons',id)?'Pelajaran ditandai selesai.':'Tanda selesai dibatalkan.');break;case 'bookmark':toggle('bookmarks',id);render();toast(state.bookmarks.includes(id)?'Bookmark disimpan.':'Bookmark dihapus.');break;case 'review-later':toggle('reviewLater',id);render();toast(state.reviewLater.includes(id)?'Ditambahkan ke tinjauan.':'Dihapus dari tinjauan.');break;case 'save-note':{const input=document.querySelector(`[data-note-id="${CSS.escape(id)}"]`);state.notes[id]=input.value;if(save()){document.querySelector('#note-status').textContent='Catatan tersimpan.';toast('Catatan disimpan.')}break}case 'try-function':{const f=data.functions.find(x=>x.name===id);ui.lastFormula=f.example.startsWith('=')?f.example:'='+f.name+'(';location.hash='#playground';break}case 'preset':ui.lastFormula=b.dataset.formula;document.querySelector('#playground-formula').value=ui.lastFormula;calculatePlayground();break;case 'reset-sheet':ui.sheet={A1:'Produk',B1:'Jumlah',C1:'Harga',A2:'P001',B2:'3',C2:'25000',A3:'P002',B3:'5',C3:'15000',A4:'P003',B4:'2',C4:'40000',A5:'P004',B5:'4',C5:'20000',D2:'=B2*C2',D3:'=B3*C3',D4:'=B4*C4',D5:'=B5*C5'};ui.lastFormula='=SUM(D2:D5)';render();break;case 'complete-case':{const c=caseStudy(id);if(completed('completedCases',id)){toggle('completedCases',id);render();break}if((state.caseChecks[id]||[]).length<c.rubric.length){toast('Tinjau dan centang seluruh rubrik sebelum menandai selesai.');break}toggle('completedCases',id);render();toast('Studi kasus ditandai selesai berdasarkan evaluasi Anda.');break}case 'ai-recommend':loadAIRecommendations(b);break;case 'logout':logoutChatGPT();break;case 'export-progress':exportProgress();break;case 'import-paste':importProgress(document.querySelector('#progress-paste').value);break;case 'reset-progress':if(window.confirm('Hapus seluruh progress, catatan, bookmark, dan riwayat di browser ini? Ekspor cadangan terlebih dahulu jika ingin menyimpannya.')){const previous=state;state=blankState();if(save()){render();toast('Progress lokal dihapus.')}else state=previous}break;case 'reload':location.reload();break}});
app.addEventListener('change',event=>{const input=event.target;if(input.id==='catalog-category'){category=input.value;render()}else if(input.id==='exercise-mode'){ui.exerciseModes[input.dataset.id]=input.value;render()}else if(input.id==='platform-setting'){state.settings.platform=input.value;save();render();toast('Preferensi Excel disimpan.')}else if(input.id==='theme-setting'){state.settings.theme=input.value;save();render()}else if(input.id==='progress-import')importProgress(input);else if(input.dataset.uploadId)gradeUpload(input);else if(input.dataset.cell){ui.sheet[input.dataset.cell]=input.value;const cells=numericSheet();document.querySelectorAll('[data-cell]').forEach(el=>{const cell=el.dataset.cell,existing=el.nextElementSibling;if(String(ui.sheet[cell]||'').startsWith('=')){const r=evaluate(ui.sheet[cell],cells);if(existing)existing.textContent=r.error||show(r.value);else{const span=document.createElement('span');span.className='sheet-result';span.textContent=r.error||show(r.value);el.after(span)}}else existing?.remove()});calculatePlayground()}else if(input.dataset.caseCheck){const id=input.dataset.caseCheck;state.caseChecks[id]||=[];const i=Number(input.value),at=state.caseChecks[id].indexOf(i);if(input.checked&&at<0)state.caseChecks[id].push(i);else if(!input.checked&&at>=0)state.caseChecks[id].splice(at,1);save()}});
app.addEventListener('input',event=>{const input=event.target;if(input.id==='catalog-filter'){filter=input.value;clearTimeout(filterTimer);const start=input.selectionStart;filterTimer=setTimeout(()=>{render();const next=document.querySelector('#catalog-filter');next?.focus();next?.setSelectionRange(start,start)},150)}else if(input.dataset.noteId){state.notes[input.dataset.noteId]=input.value;clearTimeout(noteTimer);noteTimer=setTimeout(()=>{if(save()){const status=document.querySelector('#note-status');if(status)status.textContent='Catatan tersimpan.'}},600)}});
window.addEventListener('hashchange',()=>{filter='';category='';document.querySelector('#sidebar')?.classList.remove('open');render();window.scrollTo(0,0);document.querySelector('#main')?.focus({preventScroll:true})});
window.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();document.querySelector('#global-search').focus()}if(event.key==='Escape')document.querySelector('#sidebar')?.classList.remove('open');syncSidebar()});
document.querySelector('.skip').addEventListener('click',event=>{event.preventDefault();document.querySelector('#main')?.focus()});matchMedia('(max-width:800px)').addEventListener('change',syncSidebar);window.addEventListener('pagehide',()=>save());
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();const tools=[{name:'search_excel_learning',title:'Cari materi Excel',description:'Search lessons, functions, exercises, case studies and glossary without changing progress.',inputSchema:{type:'object',properties:{query:{type:'string',minLength:1,maxLength:160}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||typeof input.query!=='string'||!input.query.trim()||input.query.length>160)throw Error('query tidak valid');return searchItems(input.query).slice(0,20).map(x=>({id:x.item.id,type:x.label,title:x.title,url:x.href}))}},{name:'read_excel_learning_progress',title:'Baca progress belajar',description:'Read current saved learning progress; no changes.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(input&&Object.keys(input).length)throw Error('Tidak menerima parameter');return {completedLessons:state.completedLessons.length,totalLessons:data.lessons.length,completedExercises:state.completedExercises.length,completedCases:state.completedCases.length,nextLesson:nextLesson().id}}},{name:'save_excel_lesson_note',title:'Simpan catatan pelajaran',description:'Save a personal note for one existing lesson and update the visible note if open.',inputSchema:{type:'object',properties:{lessonId:{type:'string'},note:{type:'string',maxLength:30000}},required:['lessonId','note'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||!lesson(input.lessonId)||typeof input.note!=='string'||input.note.length>30000)throw Error('Pelajaran atau catatan tidak valid');state.notes[input.lessonId]=input.note;if(!save())throw Error('Penyimpanan gagal');const field=document.querySelector(`[data-note-id="${CSS.escape(input.lessonId)}"]`);if(field)field.value=input.note;return {lessonId:input.lessonId,saved:true}}}];for(const t of tools)Promise.resolve(context.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
async function init(){try{const configPromise=fetch('/api/config').then(r=>r.ok?r.json():null).catch(()=>null);const [course,functions,practice,platforms]=await Promise.all(['curriculum','functions','practice','platforms'].map(async name=>{const r=await fetch('data/'+name+'.json');if(!r.ok)throw Error('Materi belum tersedia');return r.json()}));siteConfig=await configPromise||siteConfig;const allSources=[...platforms.sources,...course.lessons.flatMap(l=>l.sources||[]),...functions.map(f=>f.source)];const seen=new Set;data={...course,functions,...practice,platforms,resources:allSources.filter(s=>{if(!s?.url||seen.has(s.url))return false;seen.add(s.url);return true})};shell();render();const auth=new URLSearchParams(location.search).get('auth');if(auth){const messages={success:'Berhasil masuk dengan ChatGPT.',failed:'Login ChatGPT belum berhasil.',not_configured:'Login ChatGPT belum dikonfigurasi pada server.',secret_missing:'Client secret ChatGPT belum dikonfigurasi.'};toast(messages[auth]||'Status login diperbarui.');history.replaceState(null,'',location.pathname+location.hash)}registerTools()}catch(error){app.innerHTML=`<main class="card empty"><h1>Excel Lab belum dapat dimuat</h1><p>Periksa koneksi lalu coba kembali. Progress lokal tetap tersimpan.</p><button onclick="location.reload()">Muat ulang</button></main>`;console.error(error)}}
init();
